	// 重报 p1 与 p2 均返回各自首次登记时的结果。
	r1, err := s.RecordPayment("a", "p1", jan(2026), 400)
	if err != nil || r1.Registered || r1.BillBalance != 600 || r1.Settled {
		t.Fatalf("p1 replay: %+v %v", r1, err)
