// coverage 是一段订阅的覆盖范围，用统一的半开区间 [start, end) 表达：
// start 为开通时刻（含），end 为终止时刻（不含）；尚未终止的订阅段 end 为
// 该账户不可能早于开通时刻到达的“无限未来”哨兵，语义上等于“之后所有时刻”。
type coverage struct {
	start time.Time
	end   time.Time
}

// noEnd 是尚未终止订阅段的右端点哨兵：UTC 公元 1 年 1 月 1 日。任何合法请求
// 时刻都远晚于它，故谓词 at.Before(end) 恒为真；它只作为枚举结果出现，覆盖
// 谓词仍以真实开通/终止时刻与请求比较，不参与存储或返回值。
var noEnd = time.Date(1, time.January, 1, 0, 0, 0, 0, time.UTC)

// subCoverages 枚举账户各历史段与当前段的统一覆盖区间，按时间升序（旧 → 新）。
// 用量接收与月度出账对“订阅期间与空档”的判断都只经过这里，因此两个操作对同一
// 账户的分段、开通时刻与终止时刻依据完全一致，不再各自遍历订阅段。
//
// 未来登记的当前段以其真实开通时刻作为 start：开通之前 start <= at 不成立，
// 不会仅因账户里存有该段就让开通前的事件获得资格，也不会覆盖开通前的月份。
func subCoverages(acc *account) []coverage {
	cov := make([]coverage, 0, len(acc.history)+1)
	for _, h := range acc.history {
		cov = append(cov, coverage{start: h.activatedAt, end: *h.endedAt})
	}
	if cur := acc.sub; cur != nil {
		end := noEnd
		if cur.cancelEnd != nil {
			end = *cur.cancelEnd
		}
		cov = append(cov, coverage{start: cur.activatedAt, end: end})
	}
	return cov
}

// coversInstant 是用量归属的统一谓词：事件发生瞬间必须落在某段订阅期间内，
// 开通时刻计入、终止时刻不计入（[start, end)），只看实际瞬间而不看发生月份。
// 时刻按同一瞬间比较，使用不同时区表达结果相同。
func coversInstant(covs []coverage, at time.Time) bool {
	for _, c := range covs {
		if !at.Before(c.start) && at.Before(c.end) {
			return true
		}
	}
	return false
}

// coversMonth 是月度出账的统一谓词：账期是否“整月确实被某段订阅覆盖”。
// 它不能套用月初那一刻是否已开通：开通月计入（月中开通的当月在月末结束后仍
// 按完整月费与额度出账），故左界取月份不早于开通月；终止月不计入旧订阅
// （终止时刻所在月没有被该段整月覆盖），故右界要求整月结束不晚于终止时刻。
// 完全无订阅的空档月份、终止所在月都不满足。
//
// 与时刻谓词共用同一份 [start, end) 区间：重新开通不会把两段之间的空档变成
// 有效期间；若终止后同月重新开通，该月不满足旧段、满足新段，按新订阅条件出账。
func coversMonth(covs []coverage, period Month) bool {
	for _, c := range covs {
		if !period.Before(MonthOf(c.start)) && !period.End().After(c.end) {
			return true
		}
	}
	return false
}

// segmentForCoveredMonth 返回整月被某段订阅覆盖时该订阅段及其在枚举中的位置，
// 供出账按该段、该月当时锁定的套餐条件计价。完全无订阅覆盖的月份 ok 为 false。
// 重新开通时刻不得早于上段终止时刻，因此同一月份至多被一段整月覆盖，归属唯一。
func segmentForCoveredMonth(acc *account, covs []coverage, period Month) (*subRecord, bool) {
	// 历史段按枚举顺序与 covs 的历史前缀一一对应。
	for i, h := range acc.history {
		c := covs[i]
		if !period.Before(MonthOf(c.start)) && !period.End().After(c.end) {
			return h, true
		}
	}
	if cur := acc.sub; cur != nil {
		c := covs[len(covs)-1]
		if !period.Before(MonthOf(c.start)) && !period.End().After(c.end) {
			return cur, true
		}
	}
	return nil, false
}

// SchedulePlanChange 安排账户从下一个 UTC 自然月起改用另一套餐，升级与降级规则相同。
//
// 成功时返回目标套餐在本次安排时的完整计费条件快照与生效账期（请求被接受时的
// 下一个 UTC 自然月），之后修改套餐定义不影响本安排。当前月仍按旧套餐收取完整
// 月费并提供完整额度，不按天补差，也不迁移本月已发生的用量。
//

